var HUB_CLEAN_KINDS=['daily','midweek','eow','allergen','egg','pecan','changeover','monthly','quarterly','semiannual','annual','corrective','other'];var HUB_PLAN_KIND_MAP={full:'daily',weekly:'eow',midweek:'midweek',allergen:'allergen',changeover:'changeover'};function hubCleanKind(k){var s=String(k||'').toLowerCase().trim();if(HUB_PLAN_KIND_MAP[s])return HUB_PLAN_KIND_MAP[s];return HUB_CLEAN_KINDS.indexOf(s)>-1?s:'';}// One clean of one piece of equipment on one shift date: the key that stops a second row (MSS log craa5_completionkey).
