function hubLogRank(row){if(!row)return 0;if(hubCleanKind(row.craa5_cleankind))return hubKindRank(row.craa5_cleankind);var yes=function(v){return v===true||v===1||/^(yes|true|1)$/i.test(String(v===undefined||v===null?'':v));};return yes(row.craa5_monthly)?7:yes(row.craa5_weekly)?3:yes(row.craa5_daily)?2:9;}function hubFreqRank(code){for(var i=0;i<HUB_FREQS.length;i++)if(HUB_FREQS[i].code===code)return HUB_FREQS[i].rank;return 0;}// Period a plant day (YYYY-MM-DD) falls in, per frequency: day, Monday week, month, quarter, half year, year.
