var HUB_LANG_KEY='hub_lang';var HUB_OLD_LANG_KEYS=['itp_lang_v1','ss_lang_v1','prodsched_lang_v1','MidwestPlant_mst_lang_v1','MidwestPlant_org_lang_v1'];function hubGetLang(){try{var v=window.localStorage.getItem('__1_'+HUB_LANG_KEY);if(v==='en'||v==='es')return v;for(var i=0;i<HUB_OLD_LANG_KEYS.length;i++)if(window.localStorage.getItem('__1_'+HUB_OLD_LANG_KEYS[i])==='es')return'es';}catch(e){}return'en';}function hubSetLang(l){try{window.localStorage.setItem('__1_'+HUB_LANG_KEY,l==='es'?'es':'en');}catch(e){}}// Spanish is written in ASCII with a % code per accented letter (the PBED convention):
